#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int minIncrementForUnique(vector<int>& A) {
        sort(A.begin(), A.end());
        int result = 0, prev = -1;

        for (int num : A) {
            if (num <= prev) {
                result += prev - num + 1;
                prev++;
            } else {
                prev = num;
            }
        }

        return result;
    }
};
